add_action('after_switch_theme', 'firefront_theme_default_setup_options');
function firefront_theme_default_setup_options(){
	$default_options = firefront_get_default_options();
	update_option( 'firefront_options', json_decode( $default_options, true ) );
}

/**
* Enqueue Google Web Fonts.
